    {
      "mechanism_id": "msd_power_law",
      "statement": "The asymptotic MSD scales as a power law in time, <x^2(t)> ~ t^gamma(alpha), with exponent gamma(alpha) given piecewise. For alpha>3/2, gamma = 2 - 2/alpha.",
      "equations": [
        "gamma(alpha) = 2 - 2/alpha for alpha > 3/2",
        "<x^2(t)> ~ C(alpha) t^gamma(alpha)"
      ],
      "variable_names": ["gamma", "alpha", "t", "MSD"],
      "parameters": [
        {
          "name": "gamma_alpha2",
          "value": 1.0,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "MSD scaling exponent for alpha=2",
          "anchors": [
            {
              "line_start": 443,
              "line_end": 449,
              "support": "Piecewise gamma(alpha): for alpha>3/2, gamma = 2 - 2/alpha; at alpha=2, gamma=1."
            }
          ]
        },
        {
          "name": "gamma_alpha4",
          "value": 1.5,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "MSD scaling exponent for alpha=4",
          "anchors": [
            {
              "line_start": 443,
              "line_end": 449,
              "support": "For alpha>3/2, gamma = 2 - 2/alpha; at alpha=4, gamma=1.5."
            }
          ]
        }
      ],
      "anchors": [
        {
          "line_start": 439,
          "line_end": 449,
          "support": "Asymptotic MSD scales as t^gamma(alpha) with gamma(alpha) piecewise; for alpha>3/2, gamma=2-2/alpha."
        }
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "final_decade_scope",
