          "line_end": 508,
          "support": "In numerical simulations, the observation time is set to t = 10^8."
        }
      ]
    },
    {
      "condition_id": "rate_parameters",
      "statement": "The fluorescence rate is R(v) = (1/tau0) |v/v_r|^alpha, with v_r=1 and tau0=1.",
      "anchors": [
